        "app_name": settings.app_name,
        "admin_email": settings.admin_email,
        "items_per_user": settings.items_per_user,
    }


@app.post("/things", status_code=201, dependencies=[Depends(get_settings)])
async def update(email):
    print(get_settings())
    returned_thing = put_decision(email, get_settings())
    return {"thing": returned_thing}


def put_decision(email, settings):
    s = email
    s += " " + str(settings.items_per_user)
