from fastapi import FastAPI, Depends, Request, Body
from pydantic import BaseModel, Field
import uvicorn

app = FastAPI()


# Serializer
class RequestWithSingleExample(BaseModel):
    item_id: int = Field()
    name: str = Field()

    class Config:
        schema_extra = {
            'example': {
                'item_id': 1,
                'name': 'Name1'
            }
        }


# Serializer
class RequestWithMultiExamples(BaseModel):
    item_id: int = Field()
    name: str = Field()

    class Config:
        schema_extra = {
            'examples': {
                'example1': {
                    'summary': 'summary example1',
                    'description': 'descr example1',
                    'value': {
                        'item_id': 1,
                        'name': 'Name1'
                    }
                },
                'example2': {
                    'summary': 'summary example2',
                    'description': 'descr example2',
                    'value': {
                        'item_id': 2,
                        'name': 'Name2'
                    }
                }
            }
        }


# Depend
class RequestModelFactorySingleton(object):
    _models = {}

    def __new__(cls, model: BaseModel):
        if not cls._models.get(id(model)):
            cls._models[id(model)] = cls.query_processing_factory(model)
        return cls._models.get(id(model))

    @classmethod
    def query_processing_factory(cls, model: BaseModel):
        def processing_function(request: Request, items: model):
            # Some logic here
            return items

        return processing_function


# Endpoint with Depends and single example
# It is not possible to add multiple examples
@app.router.get('/single_example')
async def single_example(request: Request,
                         items: RequestWithSingleExample = Depends(
                             RequestModelFactorySingleton(RequestWithSingleExample))):
    return items


# Endpoint with multi examples
# It is not possible to use Depend
@app.router.get('/multi_examples')
async def multi_examples(request: Request,
                         items: RequestWithMultiExamples = Body(
                             examples=RequestWithMultiExamples.Config.schema_extra['examples'])):
    return items


# Endpoint with Depends and multi examples (examples are not displayed)
# Need support schema_extra['examples'] like schema_extra['example'] for working Depends with multi examples
@app.router.get('/multi_examples_with_depend')
async def multi_examples_with_depend(request: Request,
                                     items: RequestWithMultiExamples = Depends(
                                         RequestModelFactorySingleton(RequestWithMultiExamples))):
    return items


if __name__ == '__main__':
    uvicorn.run(app, host='0.0.0.0', port=8000)
