I'm wrinting application that uses FastAPI's sessions to uniquely identify anonymous users. I've made three endpoints:
1. `/api/session/init` - called each time by application when loading to initiate session/login user. Sets unique identifier for session. And upon session initialisation redirects to `/api/session/check`
2. `/api/session/check` - if unique identifier is present in session returns some data otherwise returns 401 response.
3. `/api/version` - simply returns application version


```python
router = APIRouter()


def get_UUID4():
    return uuid.uuid4()

@router.get("/session/init", response_class=RedirectResponse, status_code=307)
async def session_init(request: Request):
    request.session.update({"u_id": get_UUID4().hex})
    return RedirectResponse(request.url_for("session_check"))


@router.get(
    "/session/check",
    status_code=200,
    response_model=schemas.DownloadListResponse,
    responses={401: {"model": schemas.NoValidSessionError}},
)
async def session_check(request: Request):
    if not request.session.get("u_id"):
        raise HTTPException(401, "No valid session")
    return {"downloads": []}


@router.get("/version", response_model=schemas.VersionResponse, status_code=200)
async def api_version():
    """
    Endpoint for getting info about server API.
    """
    return {
        "api_version": __version__,
    }
```


