from fastapi import FastAPI, Query, Body, Depends
import pandas as pd
import numpy as np
import pyodbc
from typing import Any, List
from pydantic import BaseModel

# Load Config
config = {
    "db": {
        "DSN": "DSN",
        "UID": "UID",
        "PWD": "PWD"
    },
    "n_conn": 4,
    "port": 5000
}

DB = config["db"]
N_CONN = config.get("n_conn", 4)
PORT = config.get("port", 5000)

# Build Connection Pool
class Pool:
    def __init__(self, connect, n_conn=N_CONN):
        self.conns = [connect() for _ in range(n_conn)]
        self.current = 0
        self.n_conn = n_conn

    def connect(self):
        conn = self.conns[self.current]
        self.current = (self.current + 1) % self.n_conn
        return conn


def connect():
    dsn = ";".join([f"{key}={value}" for key, value in config["db"].items()])
    return pyodbc.connect(dsn)


pool = Pool(connect)


@Depends
def get_conn():
    return pool.connect()


# Build App
app = FastAPI()


# Build Responses
class ResponseModel(BaseModel):
    columns: List[str]
    rows: List[List[Any]]


def serialize_df(df):
    df = df.replace({np.nan: None})
    return {
        "columns": df.columns.tolist(),
        "rows": df.values.tolist(),
    }


# Routes
@app.get("/")
def root():
    print("Health Check.")
    return {"message": "All Working!"}


@app.post("/aggfunc", response_model=ResponseModel)
def aggfunc(
    start_time: str = Query(...),
    end_time: str = Query(...),
    tags: List[str] = Body(...),
    conn=get_conn,
):
    first_tag = tags[0]
    tags = ",".join(tags)
    start_time = pd.Timestamp(start_time)
    end_time = pd.Timestamp(end_time)

    sql = f"""
        SELECT Name, Timestamp, Quality, doubleval(Value) AS Value
        FROM EpmQueryAggregateFunction(
            -3, '{start_time}', '{end_time}',
            300000, 'TimeAverage',
            '{tags}'
        )
        ORDER BY Timestamp, Name;
    """

    print(f"First Tag: {first_tag} - Início")

    t0 = pd.Timestamp("now")
    df = pd.read_sql(sql, conn)
    t1 = pd.Timestamp("now")

    print(f"First Tag: {first_tag} - Fim - {(t1-t0).total_seconds():.2f}s")

    return serialize_df(df)


if __name__ == "__main__":
    import uvicorn

    uvicorn.run("main:app", host="0.0.0.0", port=PORT)
