from fastapi.openapi.utils import get_openapi
from fastapi.exceptions import RequestValidationError
from fastapi import FastAPI, Request, Response, status
import uvicorn
from pydantic import BaseModel
from fastapi import Query

app = FastAPI()

class Payload(BaseModel):
    test: str = Query(
        ..., min_length=100, max_length=200, title="test"
    )

@app.put("/items/",
responses={
        200: {
            "description": "OK"
        },
        400: {
            "description": """Validation Error
            
            This is the true status_code returned when a Validation Error occurs
            """
        },
        "4XX": {
            "description": """Validation Error
            
            ["422", "4XX", "default"] has a special meaning.
            What does the string candidate ["422", "4XX", "default"] mean? 
            Suppress the appearance of 422 in the document.
            If I don't define this, 422 will appear in the documentation.
            
            https://github.com/tiangolo/fastapi/blob/2b54432a9c78730b0dd69fca8f15d932d5a31d6b/fastapi/openapi/utils.py#L332
            """
        },
    })
async def read_items(
    payload: Payload,
):
    return [{"name": "Foo"}]


@app.exception_handler(RequestValidationError)
async def validation_exception_handler(request: Request, exc: RequestValidationError):
    return Response(
        status_code=status.HTTP_400_BAD_REQUEST,
        content="validation_failed",
    )

def custom_openapi():
    if app.openapi_schema:
        return app.openapi_schema
    openapi_schema = get_openapi(
        title="Custom title",
        version="2.5.0",
        description="This is a very custom OpenAPI schema",
        routes=app.routes,
    )
    openapi_schema["info"]["x-logo"] = {
        "url": "https://fastapi.tiangolo.com/img/logo-margin/logo-teal.png"
    }
    app.openapi_schema = openapi_schema
    return app.openapi_schema


app.openapi = custom_openapi

if __name__ == "__main__":
    uvicorn.run(
        app,
        host="0.0.0.0",
        port=8085,
    )
